SELECT `n`.`id`, `n`.`client_id`, `n`.`batch_id`, `n`.`user_id`, `n`.`template_id`, `n`.`template_version`, `n`.`channel`, `n`.`category`, `n`.`status`, `n`.`recipient_email`, `n`.`variables`, `n`.`rendered_title`, `n`.`rendered_body`, `n`.`rendered_text`, `n`.`rendered_data`, `n`.`attempt_count`, `n`.`lease_until`, `n`.`provider_message_id`, `n`.`last_error_code`, `n`.`queued_at`, `n`.`sent_at`, `n`.`delivered_at`, `n`.`read_at`, `n`.`created_at` AS n_created_at, `n`.`updated_at` FROM `notification` `n` WHERE `n`.`created_at` >= '2026-10-03 00:00:00' AND `n`.`created_at` < '2026-10-10 00:00:00' ORDER BY `n`.`created_at` DESC, `n`.`id` DESC LIMIT 51;
